int bal[MAXN];      // cumulative balance after each character
int tree[4*MAXN];   // segment tree storing minimum balance in range

int min(int a, int b) {
    return a < b ? a : b;
}

void build(int node, int l, int r) {
    if (l == r) {
        tree[node] = bal[l];
        return;
    }
    int mid = (l + r) / 2;
    build(node*2, l, mid);
    build(node*2+1, mid+1, r);
    tree[node] = min(tree[node*2], tree[node*2+1]);
}

void update(int node, int l, int r, int idx, int val) {
    if (l == r) {
        tree[node] = val;
        return;
    }
    int mid = (l + r) / 2;
    if (idx <= mid)
        update(node*2, l, mid, idx, val);
    else
        update(node*2+1, mid+1, r, idx, val);
    tree[node] = min(tree[node*2], tree[node*2+1]);
}

int query_first_negative(int node, int l, int r) {
    if (l == r) {
        return l; // found first position where balance < 0
    }
    int mid = (l + r) / 2;
    if (tree[node*2] < 0)
        return query_first_negative(node*2, l, mid);
    else
        return query_first_negative(node*2+1, mid+1, r);
}

