// segment tree for range maximum
void build_max(SegTree *st, int node, int l, int r, int *a) {
    if (l == r) {
        st->t[node] = a[l];
        return;
    }
    int m = (l + r) >> 1;
    build_max(st, node << 1, l, m, a);
    build_max(st, node << 1 | 1, m + 1, r, a);
    st->t[node] = st->t[node << 1] > st->t[node << 1 | 1] ? st->t[node << 1] : st->t[node << 1 | 1];
}

void build_min(SegTree *st, int node, int l, int r, int *a) {
    if (l == r) {
        st->t[node] = a[l];
        return;
    }
    int m = (l + r) >> 1;
    build_min(st, node << 1, l, m, a);
    build_min(st, node << 1 | 1, m + 1, r, a);
    st->t[node] = st->t[node << 1] < st->t[node << 1 | 1] ? st->t[node << 1] : st->t[node << 1 | 1];
}

void update_max(SegTree *st, int node, int l, int r, int ql, int qr, int val) {
