    if (l == r) {
        st->t[node] += val;
        return;
    }
    int m = (l + r) >> 1;
    update_max(st, node << 1, l, m, ql, qr, val);
    update_max(st, node << 1 | 1, m + 1, r, ql, qr, val);
    st->t[node] = st->t[node << 1] > st->t[node << 1 | 1] ? st->t[node << 1] : st->t[node << 1 | 1];
}

void update_min(SegTree *st, int node, int l, int r, int ql, int qr, int val) {
    if (ql > r || qr < l) return;
    if (l == r) {
        st->t[node] += val;
        return;
    }
    int m = (l + r) >> 1;
    update_min(st, node << 1, l, m, ql, qr, val);
    update_min(st, node << 1 | 1, m + 1, r, ql, qr, val);
    st->t[node] = st->t[node << 1] < st->t[node << 1 | 1] ? st->t[node << 1] : st->t[node << 1 | 1];
}

// find leftmost position with value == target in max tree
int find_first_eq_max(SegTree *st, int node, int l, int r, int target) {
    if (l == r) return l;
    int m = (l + r) >> 1;
    if (st->t[node << 1] >= target) return find_first_eq_max(st, node << 1, l, m, target);
    return find_first_eq_max(st, node << 1 | 1, m + 1, r, target);
}

// find leftmost position with value == target in min tree
int find_first_eq_min(SegTree *st, int node, int l, int r, int target) {
    if (l == r) return l;
    int m = (l + r) >> 1;
    if (st->t[node << 1] <= target) return find_first_eq_min(st, node << 1, l, m, target);
    return find_first_eq_min(st, node << 1 | 1, m + 1, r, target);
}

