struct SegmentTree {
    int n;
    vector<int> minBal, idx, lazy;

    SegmentTree(const string &s) {
        n = s.size();
        minBal.resize(4*n);
        idx.resize(4*n);
        lazy.resize(4*n, 0);
        build(1, 0, n-1, s);
    }

    void build(int node, int l, int r, const string &s) {
        if (l == r) {
            minBal[node] = (s[l] == '(' ? 1 : -1);
            idx[node] = l;
            return;
        }
        int mid = (l+r)/2;
        build(node*2, l, mid, s);
        build(node*2+1, mid+1, r, s);
        combine(node);
    }

    void combine(int node) {
        if (minBal[node*2] <= minBal[node*2+1]) {
            minBal[node] = minBal[node*2];
            idx[node] = idx[node*2];
        } else {
            minBal[node] = minBal[node*2+1];
            idx[node] = idx[node*2+1];
        }
    }

    void apply(int node, int val) {
        minBal[node] += val;
        lazy[node] += val;
    }

    void push(int node) {
        if (lazy[node] != 0) {
            apply(node*2, lazy[node]);
            apply(node*2+1, lazy[node]);
            lazy[node] = 0;
        }
    }

    void update(int node, int l, int r, int ql, int qr, int val) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            apply(node, val);
            return;
        }
        push(node);
        int mid = (l+r)/2;
        update(node*2, l, mid, ql, qr, val);
        update(node*2+1, mid+1, r, ql, qr, val);
        combine(node);
    }

    int queryPos() {
        // find leftmost position where min balance < 0
        return findFirstNegative(1, 0, n-1, 0);
    }

    int findFirstNegative(int node, int l, int r, int carry) {
        if (l == r) {
            return l;
        }
        push(node);
        int mid = (l+r)/2;
        int leftMin = minBal[node*2] + lazy[node*2];
        // We need prefix sums, but we can handle via carry
        if (carry + minBal[node*2] < 0) {
            return findFirstNegative(node*2, l, mid, carry);
        } else {
            return findFirstNegative(node*2+1, mid+1, r, carry + minBal[node*2]);
        }
    }
};

