/*
We have a balanced parentheses string s of length n.
For each query, one bracket at position x is flipped.
Now the string becomes unbalanced by exactly 2 in total sum:
- '(' -> ')' makes total sum = -2, so we must flip some ')' to '('
- ')' -> '(' makes total sum = +2, so we must flip some '(' to ')'

We need the leftmost position whose flip restores balance.

Known approach:
Let a[i] = +1 for '(', -1 for ')', prefix sums p[i].

If we flip position x:
1) '(' -> ')': all prefix sums from x..n decrease by 2.
   To restore total sum, flip some position y with current char ')'
   (after first flip) to '('; this adds +2 to prefixes y..n.
   For balance, we need y to be the first position where modified prefix becomes -1.
   This is equivalent to the leftmost position with prefix value 1 in the original string
   among positions >= x. We flip a ')' there.
   Standard implementation uses sets of positions of ')' and segment tree over prefix sums.
   Find first position >= x where current minimum prefix on [x..pos] reaches -1 after update,
   or equivalently after applying first flip. Easier done directly with segment tree current state.

2) ')' -> '(': all prefix sums from x..n increase by 2.
   Need flip some '(' to ')', leftmost such position.
   This becomes the leftmost '(' position <= something determined by the last place where prefix becomes 1 too large.
   Symmetric trick: use reversed transformed string or directly use maximum prefix.
   Simpler standard solution:
   Maintain current string always balanced after handling each query.
   Also maintain:
     open positions set, close positions set.
   For query x:
   - If s[x]=='(':
       flip it to ')'
       answer = smallest position in close_positions
       among positions >= x? Actually for the classic problem "Sereja and Brackets?" no.
   Need exact leftmost restoring flip for balanced string after one forced flip.
*/

struct SegTree {
    int n;
    vector<int> mn, mx, lazy;

    SegTree() {}
    SegTree(const vector<int>& a) { init(a); }

    void init(const vector<int>& a) {
        n = (int)a.size() - 1; // 1-indexed
        mn.assign(4*n+4, 0);
        mx.assign(4*n+4, 0);
        lazy.assign(4*n+4, 0);
        build(1,1,n,a);
    }

    void build(int v,int l,int r,const vector<int>& a){
        if(l==r){
            mn[v]=mx[v]=a[l];
            return;
        }
        int m=(l+r)>>1;
        build(v<<1,l,m,a);
        build(v<<1|1,m+1,r,a);
        pull(v);
    }

    void pull(int v){
        mn[v]=min(mn[v<<1], mn[v<<1|1]);
        mx[v]=max(mx[v<<1], mx[v<<1|1]);
    }

    void apply(int v,int val){
        mn[v]+=val;
        mx[v]+=val;
        lazy[v]+=val;
    }

    void push(int v){
        if(lazy[v]){
            apply(v<<1,lazy[v]);
            apply(v<<1|1,lazy[v]);
            lazy[v]=0;
        }
    }

    void add(int v,int l,int r,int ql,int qr,int val){
        if(ql>r || qr<l) return;
        if(ql<=l && r<=qr){
            apply(v,val);
            return;
        }
        push(v);
        int m=(l+r)>>1;
        add(v<<1,l,m,ql,qr,val);
        add(v<<1|1,m+1,r,ql,qr,val);
        pull(v);
    }

    void add(int l,int r,int val){
        if(l<=r) add(1,1,n,l,r,val);
    }

    // first position with prefix minimum < 0
    int firstNeg(int v,int l,int r){
        if(l==r) return l;
        push(v);
        int m=(l+r)>>1;
        if(mn[v<<1] < 0) return firstNeg(v<<1,l,m);
        return firstNeg(v<<1|1,m+1,r);
    }

    // last position with prefix maximum > 0
    int lastPos(int v,int l,int r){
        if(l==r) return l;
        push(v);
        int m=(l+r)>>1;
        if(mx[v<<1|1] > 0) return lastPos(v<<1|1,m+1,r);
        return lastPos(v<<1,l,m);
    }

    int globalMin() const { return mn[1]; }
    int globalMax() const { return mx[1]; }
};

