            cout << y << "\n";

            s[y]='(';
            closes.erase(y);
            opens.insert(y);
            st.add(y,n,+2);
        }else{
            // forced flip ')' -> '('
            s[x]='(';
            closes.erase(x);
            opens.insert(x);
            st.add(x,n,+2);

            int y = st.lastPos(1,1,n); // last prefix > 0
