public class Main {
    // Segment tree storing min and max prefix sums on a segment
    static class SegTree {
        int n;
        int[] min, max, lazy;

        SegTree(int n) {
            this.n = n;
            int sz = 4 * n + 5;
            min = new int[sz];
            max = new int[sz];
            lazy = new int[sz];
        }

        void build(int node, int l, int r, int[] pref) {
            if (l == r) {
                min[node] = max[node] = pref[l];
                return;
            }
            int mid = (l + r) >>> 1;
            build(node << 1, l, mid, pref);
            build(node << 1 | 1, mid + 1, r, pref);
            pull(node);
        }

        void pull(int node) {
            min[node] = Math.min(min[node << 1], min[node << 1 | 1]);
            max[node] = Math.max(max[node << 1], max[node << 1 | 1]);
        }

        void apply(int node, int val) {
            min[node] += val;
            max[node] += val;
            lazy[node] += val;
        }

        void push(int node) {
            if (lazy[node] != 0) {
                apply(node << 1, lazy[node]);
                apply(node << 1 | 1, lazy[node]);
                lazy[node] = 0;
            }
        }

        void rangeAdd(int node, int l, int r, int ql, int qr, int val) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                apply(node, val);
                return;
            }
            push(node);
            int mid = (l + r) >>> 1;
            rangeAdd(node << 1, l, mid, ql, qr, val);
            rangeAdd(node << 1 | 1, mid + 1, r, ql, qr, val);
            pull(node);
        }

        int findFirstMinLessThan(int node, int l, int r, int x) {
            if (min[node] >= x) return -1;
            if (l == r) return l;
            push(node);
            int mid = (l + r) >>> 1;
            if (min[node << 1] < x) return findFirstMinLessThan(node << 1, l, mid, x);
            return findFirstMinLessThan(node << 1 | 1, mid + 1, r, x);
        }

        int findFirstMaxGreaterThan(int node, int l, int r, int x) {
            if (max[node] <= x) return -1;
            if (l == r) return l;
            push(node);
            int mid = (l + r) >>> 1;
            if (max[node << 1] > x) return findFirstMaxGreaterThan(node << 1, l, mid, x);
            return findFirstMaxGreaterThan(node << 1 | 1, mid + 1, r, x);
        }
    }

