        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int q = fs.nextInt();
        char[] s = fs.next().toCharArray();

        int[] pref = new int[n];
        int bal = 0;
        for (int i = 0; i < n; i++) {
            bal += (s[i] == '(' ? 1 : -1);
            pref[i] = bal;
        }

        SegTree st = new SegTree(n);
        st.build(1, 0, n - 1, pref);

        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < q; qi++) {
            int pos = fs.nextInt() - 1;

            if (s[pos] == '(') {
                // Flip '(' -> ')', all suffix prefixes decrease by 2
                st.rangeAdd(1, 0, n - 1, pos, n - 1, -2);
                s[pos] = ')';

                // Need leftmost position with prefix < 0, flip that ')' to '('
                int j = st.findFirstMinLessThan(1, 0, n - 1, 0);

                st.rangeAdd(1, 0, n - 1, j, n - 1, +2);
                s[j] = '(';

                out.append(j + 1).append('\n');
            } else {
                // Flip ')' -> '(', all suffix prefixes increase by 2
                st.rangeAdd(1, 0, n - 1, pos, n - 1, +2);
                s[pos] = '(';

                // Need leftmost position with prefix > 1, flip that '(' to ')'
                int j = st.findFirstMaxGreaterThan(1, 0, n - 1, 1);

                st.rangeAdd(1, 0, n - 1, j, n - 1, -2);
                s[j] = ')';

                out.append(j + 1).append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import sys
input = sys.stdin.readline

class SegTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.minv = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)
        for i in range(self.n):
            self.minv[self.size + i] = data[i]
        for i in range(self.size - 1, 0, -1):
            self.minv[i] = min(self.minv[2*i], self.minv[2*i+1])

    def _apply(self, idx, val):
        self.minv[idx] += val
        self.lazy[idx] += val

    def _push(self, idx):
        if self.lazy[idx] != 0:
            self._apply(2*idx, self.lazy[idx])
            self._apply(2*idx+1, self.lazy[idx])
            self.lazy[idx] = 0

    def range_add(self, l, r, val, idx=1, left=0, right=None):
        if right is None:
            right = self.size - 1
        if l > r:
            return
        if l == left and r == right:
            self._apply(idx, val)
            return
        self._push(idx)
        mid = (left + right) // 2
        if r <= mid:
            self.range_add(l, r, val, 2*idx, left, mid)
        elif l > mid:
            self.range_add(l, r, val, 2*idx+1, mid+1, right)
        else:
            self.range_add(l, mid, val, 2*idx, left, mid)
            self.range_add(mid+1, r, val, 2*idx+1, mid+1, right)
        self.minv[idx] = min(self.minv[2*idx], self.minv[2*idx+1])

    def query_min(self, l, r, idx=1, left=0, right=None):
        if right is None:
            right = self.size - 1
        if l > r:
            return 10**18
        if l == left and r == right:
            return self.minv[idx]
        self._push(idx)
        mid = (left + right) // 2
        if r <= mid:
            return self.query_min(l, r, 2*idx, left, mid)
        elif l > mid:
            return self.query_min(l, r, 2*idx+1, mid+1, right)
        else:
            return min(self.query_min(l, mid, 2*idx, left, mid),
                       self.query_min(mid+1, r, 2*idx+1, mid+1, right))

    def first_less_than(self, target):
        # find smallest index i such that prefix sum (i.e., value at i) < target
        idx = 1
        if self.minv[idx] >= target:
            return -1
        left, right = 0, self.size - 1
        while left < right:
            self._push(idx)
            mid = (left + right) // 2
            if self.minv[2*idx] < target:
                idx = 2*idx
                right = mid
            else:
                idx = 2*idx + 1
                left = mid + 1
        return left

def solve():
    n, q = map(int, input().split())
    s = list(input().strip())
    # prefix sums
    pref = [0] * n
    bal = 0
    for i in range(n):
        if s[i] == '(':
            bal += 1
        else:
            bal -= 1
        pref[i] = bal

    seg = SegTree(pref)

    out_lines = []
    for _ in range(q):
        pos = int(input()) - 1  # 0-based
        # flip at pos
        if s[pos] == '(':
            s[pos] = ')'
            seg.range_add(pos, n-1, -2)
        else:
            s[pos] = '('
            seg.range_add(pos, n-1, +2)

        total = seg.query_min(n-1, n-1)
        if total > 0:
            # need to flip ) to ( somewhere
            # first position where prefix sum < 1 (i.e., <=0)
            target = 1
        else:
            # need to flip ( to ) somewhere
            target = total  # find where value < total (negative means we need to increase)

        ans = seg.first_less_than(target)
        out_lines.append(str(ans+1))  # convert to 1-based

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
